// Webhook CSV receiver & Robust CSV Parser
const item = $input.first();
const binary = item.binary || {};

let binaryProperty = null;
if (binary.data) {
  binaryProperty = 'data';
} else {
  const keys = Object.keys(binary);
  if (keys.length) binaryProperty = keys[0];
}

if (!binaryProperty) {
  throw new Error('No CSV file received by the webhook. In Postman/cURL, use Body -> form-data with key "data" set to Type=File.');
}

const buf = await this.helpers.getBinaryDataBuffer(0, binaryProperty);
if (!buf || !buf.length) {
  throw new Error(`Received an empty file in binary property "${binaryProperty}".`);
}

const text = buf.toString('utf8').replace(/^\uFEFF/, '').trim();
if (!text) throw new Error('The uploaded CSV file is empty.');

function parseCSV(text) {
  const rows = [];
  let row = [];
  let cell = '';
  let quoted = false;

  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    const next = text[i + 1];

    if (c === '"') {
      if (quoted && next === '"') {
        cell += '"';
        i++;
      } else {
        quoted = !quoted;
      }
    } else if (c === ',' && !quoted) {
      row.push(cell);
      cell = '';
    } else if ((c === '\n' || c === '\r') && !quoted) {
      if (c === '\r' && next === '\n') i++;
      row.push(cell);
      cell = '';
      if (row.some(v => String(v).trim() !== '')) rows.push(row);
      row = [];
    } else {
      cell += c;
    }
  }
  if (cell.length || row.length) {
    row.push(cell);
    if (row.some(v => String(v).trim() !== '')) rows.push(row);
  }
  return rows;
}

const rows = parseCSV(text);
if (rows.length < 2) {
  throw new Error('CSV must contain a header row and at least one article title.');
}

const headers = rows[0].map(h => String(h).trim().toLowerCase());
let titleIndex = headers.findIndex(h => ['title', 'article title', 'article_title', 'headline'].includes(h));
if (titleIndex === -1) titleIndex = 0;

const output = [];
for (let r = 1; r < rows.length; r++) {
  const title = String(rows[r][titleIndex] ?? '').trim();
  if (!title) continue;

  output.push({
    json: {
      articleId: `article-${r}-${Date.now()}`,
      title,
      sourceRow: r + 1,
      sourceFile: item.binary?.[binaryProperty]?.fileName || 'uploaded.csv',
      status: 'queued'
    }
  });
}

if (!output.length) {
  throw new Error(`No article titles found in column "${rows[0][titleIndex] || 'first column'}".`);
}

return output;

