const responseText = $json.choices?.[0]?.message?.content || '';
if (!responseText) throw new Error(`No text returned by OpenAI for "${$json.title}".`);

const cleaned = responseText.trim().replace(/^```json\s*/i, '').replace(/\s*```$/, '');
let article;
try {
  article = JSON.parse(cleaned);
} catch (e) {
  throw new Error(`Invalid JSON from GPT-4o for "${$json.title}": ${e.message}`);
}

const nMatch = String($json.title).match(/\b(\d{1,3})\b/);
const expectedSections = nMatch ? parseInt(nMatch[1], 10) : 8;

if (!Array.isArray(article.sections) || article.sections.length !== expectedSections) {
  throw new Error(`Section count mismatch for "${$json.title}". Expected ${expectedSections}, got ${article.sections?.length || 0}.`);
}

for (let i = 0; i < article.sections.length; i++) {
  const s = article.sections[i];
  if (!s.heading || !s.description || !s.image_prompt) {
    throw new Error(`Section ${i + 1} is missing heading, description, or image_prompt.`);
  }
  const sentences = String(s.description).split(/(?<=[.!?])\s+/).filter(Boolean);
  if (sentences.length < 5 || sentences.length > 6) {
    throw new Error(`Section ${i + 1} must contain 5-6 sentences; got ${sentences.length}.`);
  }
  s.number = i + 1;
}

return [{
  json: {
    articleId: $json.articleId,
    title: article.title || $json.title,
    introduction: article.introduction || '',
    conclusion: article.conclusion || '',
    sections: article.sections,
    expectedSections: expectedSections,
    status: 'article_generated'
  }
}];

const outputs = [];
const faceProfiles = [
  "A distinct adult woman with an oval face, warm olive complexion, and gentle brown eyes",
  "A distinct adult woman with a heart-shaped face, soft freckles, and green eyes",
  "A distinct adult woman with a square jawline, warm golden complexion, and hazel eyes",
  "A distinct adult woman with a round face, fair complexion, and expressive blue eyes",
  "A distinct adult woman with high cheekbones, diamond face shape, and deep dark eyes",
  "A distinct adult woman with a long face shape, subtle beauty mark, and amber eyes",
  "A distinct adult woman with soft arched eyebrows, natural complexion, and light brown eyes",
  "A distinct adult woman with an oval face, rich bronze complexion, and dark eyes",
  "A distinct adult woman with a heart-shaped face, rosy cheeks, and bright blue eyes",
  "A distinct adult woman with a square face shape, soft features, and hazel green eyes",
  "A distinct adult woman with a round face, sun-kissed skin tone, and warm brown eyes",
  "A distinct adult woman with high cheekbones, elegant features, and dark grey eyes"
];

for (const item of $input.all()) {
  const a = item.json;
  for (let i = 0; i < a.sections.length; i++) {
    const s = a.sections[i];
    const faceIdentity = faceProfiles[i % faceProfiles.length] + `; unique face variant ${i + 1} for this article`;
    outputs.push({
      json: {
        articleId: a.articleId,
        title: a.title,
        introduction: a.introduction,
        conclusion: a.conclusion,
        expectedSections: a.expectedSections,
        sectionNumber: i + 1,
        sectionTitle: s.heading,
        description: s.description,
        baseImagePrompt: s.image_prompt,
        faceIdentity: faceIdentity
      }
    });
  }
}
return outputs;

