const imgRes = $json.data?.[0];
const b64 = imgRes?.b64_json;
const url = imgRes?.url;

let imageDataUri = '';
if (b64) {
  imageDataUri = `data:image/png;base64,${b64}`;
} else if (url) {
  imageDataUri = url;
} else {
  throw new Error(`DALL-E 3 failed for article ${$json.articleId}, section ${$json.sectionNumber}. No image data returned.`);
}

return [{
  json: {
    articleId: $json.articleId,
    title: $json.title,
    introduction: $json.introduction,
    conclusion: $json.conclusion,
    expectedSections: $json.expectedSections,
    sectionNumber: $json.sectionNumber,
    sectionTitle: $json.sectionTitle,
    description: $json.description,
    imageDataUri: imageDataUri,
    status: 'image_generated'
  }
}];

const groups = new Map();
for (const item of $input.all()) {
  const j = item.json;
  if (!groups.has(j.articleId)) groups.set(j.articleId, []);
  groups.get(j.articleId).push(j);
}

const results = [];
for (const [articleId, sections] of groups) {
  sections.sort((a, b) => a.sectionNumber - b.sectionNumber);
  const title = sections[0].title;
  const intro = sections[0].introduction;
  const conclusion = sections[0].conclusion;

  const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

  // Generate WordPress / Blogger HTML
  let html = `<article class="ai-seo-article">\n<h1>${esc(title)}</h1>\n\n<p class="intro">${esc(intro)}</p>\n\n`;
  for (const s of sections) {
    html += `<h2>${s.sectionNumber}. ${esc(s.sectionTitle)}</h2>\n`;
    html += `<figure><img src="${s.imageDataUri}" alt="${esc(s.sectionTitle)}" loading="lazy" style="max-width:100%;height:auto;border-radius:8px;" /></figure>\n`;
    html += `<p>${esc(s.description)}</p>\n\n`;
  }
  html += `<h2>Conclusion</h2>\n<p class="conclusion">${esc(conclusion)}</p>\n</article>`;

  // Generate Markdown
  let markdown = `# ${title}\n\n${intro}\n\n`;
  markdown += sections.map(s => `## ${s.sectionNumber}. ${s.sectionTitle}\n\n![${s.sectionTitle}](${s.imageDataUri})\n\n${s.description}`).join('\n\n');
  markdown += `\n\n## Conclusion\n\n${conclusion}`;

  results.push({
    json: {
      success: true,
      articleId,
      title,
      totalSections: sections.length,
      htmlOutput: html,
      markdownOutput: markdown,
      publishingReady: {
        wordpressFormat: html,
        bloggerFormat: html,
        markdownFormat: markdown
      }
    }
  });
}

return results;
